interface Shape {
    fun area(): Double
}

class Circle(private val r: Double) : Shape {
    override fun area() = Math.PI * r * r
}

fun String.isPalindrome(): Boolean {
    val clean = lowercase().filter { it.isLetterOrDigit() }
    return clean == clean.reversed()
}
